edits:
source "${FLEET_SKILLS:?}/_shared/repo-config.sh" && fleet_load_issue_config "${FLEET_TARGET_REPO:?}" || { echo "Cannot verify issue-linking policy" >&2; return 1 2>/dev/null || exit 1; }
ISSUE_CONFIG_OID=$RC_TRUSTED_OID
export GH_REPO="$RC_TRUSTED_REPO"

source "${FLEET_SKILLS:?}/_shared/repo-config.sh" && fleet_load_issue_config "${FLEET_TARGET_REPO:?}" "${ISSUE_CONFIG_OID:?use the revision recorded at intake}" || { echo "Issue intake configuration changed or is unavailable; stop and refresh the preview" >&2; return 1 2>/dev/null || exit 1; }
export GH_REPO="$RC_TRUSTED_REPO"
OWNER_REPO=$RC_TRUSTED_REPO

case "${ISSUE_CREATE_CHOICE:-}" in
  cancel) return 0 2>/dev/null || exit 0 ;;
  parent-only) ISSUE_BODY_FILE="$ISSUE_DRAFT/parent-only.md" ;;
  create|absorb) ISSUE_BODY_FILE="$ISSUE_DRAFT/body.md" ;;
  *) echo "Missing issue creation decision" >&2; return 1 2>/dev/null || exit 1 ;;
esac
source "${FLEET_SKILLS:?}/_shared/repo-config.sh" && fleet_load_issue_config "${FLEET_TARGET_REPO:?}" "${ISSUE_CONFIG_OID:?use the revision recorded at intake}" || { echo "Issue intake configuration changed or is unavailable; stop and refresh the preview" >&2; return 1 2>/dev/null || exit 1; }
export GH_REPO="$RC_TRUSTED_REPO"
ACTUAL_BODY_OID=$(git hash-object --no-filters -- "$ISSUE_BODY_FILE") &&
  [ "$ACTUAL_BODY_OID" = "${APPROVED_BODY_OID:?record the selected preview OID}" ] ||
  { echo "Selected preview changed" >&2; return 1 2>/dev/null || exit 1; }
jq -en --rawfile title "$ISSUE_DRAFT/title.txt" --rawfile body "$ISSUE_BODY_FILE" \
  --slurpfile labels "$ISSUE_DRAFT/labels.json" --arg milestone "${MILESTONE_NUMBER:-}" '
  ($title | sub("\r?\n$"; "")) as $title |
  select(($title | length) > 0 and ($title | test("[\r\n]") | not)) |
  select(($labels | length) == 1 and ($labels[0] | type == "array" and all(.[]; type == "string"))) |
  {title: $title, body: $body, labels: $labels[0]} +
  (if $milestone == "" then {} else
     select($milestone | test("^[1-9][0-9]*$")) | {milestone: ($milestone | tonumber)} end)
' > "$ISSUE_DRAFT/create.json" || { echo "Invalid issue draft" >&2; return 1 2>/dev/null || exit 1; }
gh api --hostname github.com --method POST "repos/$RC_TRUSTED_REPO/issues" \
  --input "$ISSUE_DRAFT/create.json" > "$ISSUE_DRAFT/receipt.json" 2>/dev/null || { echo "Creation receipt unavailable; reconcile before retry" >&2; return 1 2>/dev/null || exit 1; }
jq -e --arg repo "$RC_TRUSTED_REPO" --slurpfile draft "$ISSUE_DRAFT/create.json" '
  select(.number | type == "number" and floor == . and . > 0) |
  select(.html_url == ("https://github.com/" + $repo + "/issues/" + (.number | tostring))) |
  {url: .html_url, number, metadata_matches: (
    .title == $draft[0].title and .body == $draft[0].body and
    ([.labels[].name] | sort) == ($draft[0].labels | sort) and .milestone.number == $draft[0].milestone)}
' "$ISSUE_DRAFT/receipt.json"

FLEET_TARGET_REPO="$OWNER_REPO"
CONFIG_STATE=ok
source "${FLEET_SKILLS:?}/_shared/repo-config.sh" && fleet_load_repo_config "$OWNER_REPO" || { CONFIG_STATE=unreadable; echo "Unverified repository configuration" >&2; return 2 2>/dev/null || exit 2; }
